export function auditTextPage(items,{width,height},pageNumber){const issues=[];let meaningful=0;for(const item of items){if(!item.str?.trim())continue;if(item.str.trim().length>3)meaningful++;const [a,b,c,d,x,y]=item.transform||[];if(![x,y,item.width].every(Number.isFinite))continue;const h=Math.abs(item.height||d||a||10);if(x<-.8||x+item.width>width+.8||y<-.8||y-h>height+.8)issues.push({code:'outside-page',page:pageNumber,message:'Text liegt außerhalb der Seite; auf abgeschnittenen Inhalt prüfen.'});if(/[\uFFFD\u25A1]/u.test(item.str))issues.push({code:'glyph',page:pageNumber,message:'Mögliches Ersatzzeichen oder fehlendes Schriftzeichen.'});}if(meaningful<2)issues.push({code:'nearly-empty',page:pageNumber,message:'Fast leere Übersetzungsseite; Seitenumbruch prüfen.'});return issues.filter((v,i,a)=>a.findIndex(x=>x.code===v.code)===i);}
